-- ==========================================
-- REMOVE PREVIOUSLY SEEDED EVENT DATA (id prefixes 10/20/30/40/50/60/70)
-- Children are deleted before parents so no FK violations occur. This makes
-- the script a true full-replace on every run, unlike a plain upsert.
-- ==========================================
DELETE FROM public.notification_recipients WHERE id::text LIKE '70%';
DELETE FROM public.notifications WHERE id::text LIKE '60%';
DELETE FROM public.attendance_records WHERE id::text LIKE '40%';
DELETE FROM public.transportation_details WHERE id::text LIKE '50%';
DELETE FROM public.registrations WHERE id::text LIKE '30%';
DELETE FROM public.event_details WHERE id::text LIKE '20%';
DELETE FROM public.events WHERE id::text LIKE '10%';

