-- ==========================================
-- SEED EVENT DETAILS
-- Descriptions intentionally omit the event title/location (already shown
-- elsewhere in the UI) and use colors/bold/italic/list formatting only for
-- the agenda/audience/inclusions. Posters are real PNGs, cycled round-robin
-- across the 6 available files: the first 6 events embed the literal binary,
-- the rest reference it via a scalar subquery to avoid repeating the same
-- image 20 times. No QR codes are generated (qr_code_content stays NULL).
-- Event codes are 6-digit numeric strings matching the app's own format.
-- ==========================================
INSERT INTO public.event_details (id, event_id, description, poster, food_provided, qr_code_content, event_code) VALUES 
('20000001-0000-0000-0000-000000000000', '10000001-0000-0000-0000-000000000000', '<p>Standuri de prezentare si interviuri rapide organizate impreuna cu Universitatea Babes-Bolyai, dedicate studentilor interesati de o cariera in IT.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#6a1b9a;font-weight:bold;">Agenda:</span> Prezentari despre echipele tehnice, interviuri pe loc si sesiuni de intrebari si raspunsuri.</li><li><span style="color:#6a1b9a;font-weight:bold;">Public tinta:</span> Studenti si proaspeti absolventi de informatica si domenii conexe.</li><li><span style="color:#6a1b9a;font-weight:bold;">Inclus:</span> Brosuri, teste de aptitudini si feedback direct de la recrutori.</li></ul><p style="color:#607d8b;"><em>Multumim tuturor studentilor care au trecut pe la standul nostru.</em></p>', decode('','base64'), false, NULL, '482913'),
('20000002-0000-0000-0000-000000000000', '10000002-0000-0000-0000-000000000000', '<p>Actiune de voluntariat organizata de colegii din Targu Mures, dedicata curatarii unui spatiu verde din oras.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#00695c;font-weight:bold;">Agenda:</span> Impartirea pe echipe, colectarea deseurilor si o mica intalnire de multumire la final.</li><li><span style="color:#00695c;font-weight:bold;">Public tinta:</span> Angajati voluntari si familiile acestora.</li><li><span style="color:#00695c;font-weight:bold;">Inclus:</span> Echipament de protectie, apa si gustari pentru voluntari.</li></ul><p style="color:#607d8b;"><em>O reusita colectiva care a lasat orasul un pic mai curat.</em></p>', decode('','base64'), true, NULL, '671204'),
('20000003-0000-0000-0000-000000000000', '10000003-0000-0000-0000-000000000000', '<p>Zi sportiva dedicata colegilor din Timisoara, cu mai multe discipline si activitati de echipa.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#00695c;font-weight:bold;">Agenda:</span> Turnee de fotbal si volei, probe de atletism si activitati recreative.</li><li><span style="color:#00695c;font-weight:bold;">Public tinta:</span> Angajati pasionati de sport din toate departamentele.</li><li><span style="color:#00695c;font-weight:bold;">Inclus:</span> Echipament sportiv, apa si gustari energizante.</li></ul><p style="color:#607d8b;"><em>Felicitari tuturor echipelor pentru implicare si fair-play.</em></p>', decode('','base64'), true, NULL, '305587'),
('20000004-0000-0000-0000-000000000000', '10000004-0000-0000-0000-000000000000', '<p>Gala organizata cu ocazia aniversarii biroului din Cluj, cu un program artistic si momente aniversare.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#00695c;font-weight:bold;">Agenda:</span> Cina festiva, discursuri aniversare si program de divertisment.</li><li><span style="color:#00695c;font-weight:bold;">Public tinta:</span> Toti angajatii biroului din Cluj si invitati speciali.</li><li><span style="color:#00695c;font-weight:bold;">Inclus:</span> Cina festiva, bauturi si program artistic.</li></ul><p style="color:#607d8b;"><em>Multumim tuturor celor care au sarbatorit alaturi de noi.</em></p>', decode('','base64'), true, NULL, '918042'),
('20000005-0000-0000-0000-000000000000', '10000005-0000-0000-0000-000000000000', '<p>Campanie interna de donare de sange, organizata in parteneriat cu centrul local de transfuzie sanguina.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Inscriere, control medical rapid si donare sub supravegherea personalului medical.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Angajati eligibili pentru donare din toate locatiile.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Gustari si bauturi dupa donare, plus timp liber acordat donatorilor.</li></ul><p style="color:#607d8b;"><em>Multumim donatorilor pentru gestul lor generos.</em></p>', decode('','base64'), true, NULL, '247761'),
('20000006-0000-0000-0000-000000000000', '10000006-0000-0000-0000-000000000000', '<p>Sesiune interna de prezentari tehnice despre tendintele actuale in cloud computing si inteligenta artificiala.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Prezentari scurte urmate de sesiuni de intrebari si discutii libere.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Ingineri software, arhitecti si oricine interesat de tehnologie.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Inregistrari video disponibile ulterior si materiale de prezentare.</li></ul><p style="color:#607d8b;"><em>Discutiile continua in canalul intern dedicat tehnologiei.</em></p>', decode('','base64'), true, NULL, '563390'),
('20000007-0000-0000-0000-000000000000', '10000007-0000-0000-0000-000000000000', '<p>Eveniment dedicat copiilor colegilor nostri, cu activitati educative si distractive la birou.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#00695c;font-weight:bold;">Agenda:</span> Ateliere creative, jocuri de echipa si un tur al biroului.</li><li><span style="color:#00695c;font-weight:bold;">Public tinta:</span> Copiii angajatilor si parintii lor.</li><li><span style="color:#00695c;font-weight:bold;">Inclus:</span> Gustari, materiale pentru ateliere si mici cadouri surpriza.</li></ul><p style="color:#607d8b;"><em>Multumim tuturor familiilor care au participat cu drag.</em></p>', decode('','base64'), true, NULL, '129485'),
('20000008-0000-0000-0000-000000000000', '10000008-0000-0000-0000-000000000000', '<p>Petrecere de iarna organizata pentru echipa din Targu Mures, cu muzica si atmosfera de sarbatoare.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Cina festiva, tombola si moment muzical live.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Toti angajatii biroului din Targu Mures.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Cina, bauturi si premii la tombola.</li></ul><p style="color:#607d8b;"><em>Un final de an petrecut impreuna, asa cum se cuvine.</em></p>', decode('','base64'), true, NULL, '874026'),
('20000009-0000-0000-0000-000000000000', '10000009-0000-0000-0000-000000000000', '<p>Seara dedicata partenerilor si colaboratorilor externi din regiunea Timisoara, ca semn de apreciere pentru colaborarea din acest an.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#6a1b9a;font-weight:bold;">Agenda:</span> Cocktail de bun venit, scurte discursuri si sesiune de networking.</li><li><span style="color:#6a1b9a;font-weight:bold;">Public tinta:</span> Parteneri de afaceri si colaboratori externi.</li><li><span style="color:#6a1b9a;font-weight:bold;">Inclus:</span> Aperitive si bauturi pe parcursul serii.</li></ul><p style="color:#607d8b;"><em>Multumim partenerilor nostri pentru increderea acordata.</em></p>', decode('','base64'), false, NULL, '356910'),
('20000010-0000-0000-0000-000000000000', '10000010-0000-0000-0000-000000000000', '<p>Sustinerea unei alergari caritabile locale, cu un stand propriu si o echipa de alergatori din companie.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#00695c;font-weight:bold;">Agenda:</span> Incalzire in grup, cursa propriu-zisa si festivitate de premiere.</li><li><span style="color:#00695c;font-weight:bold;">Public tinta:</span> Angajati alergatori si comunitatea locala.</li><li><span style="color:#00695c;font-weight:bold;">Inclus:</span> Tricouri personalizate si puncte de hidratare sponsorizate.</li></ul><p style="color:#607d8b;"><em>Felicitari echipei noastre de alergatori pentru implicare.</em></p>', decode('','base64'), true, NULL, '691247'),
('20000011-0000-0000-0000-000000000000', '10000011-0000-0000-0000-000000000000', '<p>Editie interna de hackathon in care echipele vor dezvolta prototipuri inovatoare intr-un timp limitat.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Formarea echipelor, dezvoltare de prototip si prezentari finale in fata unui juriu.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Dezvoltatori, designeri si product manageri din toate echipele.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Detalii despre catering si premii in curs de definitivare.</li></ul><p style="color:#607d8b;"><em>Programul final va fi comunicat dupa aprobarea agendei.</em></p>', decode('','base64'), true, NULL, '742038'),
('20000012-0000-0000-0000-000000000000', '10000012-0000-0000-0000-000000000000', '<p>Zi de integrare dedicata noilor colegi, cu prezentari despre cultura organizationala si echipele companiei.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Prezentari generale, cunoasterea echipelor si un tur al biroului.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Noii angajati din toate departamentele.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Materiale de bun venit si pranz alaturi de echipa.</li></ul><p style="color:#607d8b;"><em>Agenda finala va fi confirmata inainte de eveniment.</em></p>', decode('','base64'), true, NULL, '280516'),
('20000013-0000-0000-0000-000000000000', '10000013-0000-0000-0000-000000000000', '<p>Intalnire de planificare strategica pentru echipa de conducere, aflata inca in etapa de organizare.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Sesiuni de strategie, workshop-uri si activitati de team-building.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Management si lideri de echipa.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Cazare si mese incluse pe durata evenimentului.</li></ul><p style="color:#607d8b;"><em>Agenda finala va fi comunicata dupa aprobarea bugetului.</em></p>', decode('','base64'), true, NULL, '937164'),
('20000014-0000-0000-0000-000000000000', '10000014-0000-0000-0000-000000000000', '<p>Targ de cariera organizat impreuna cu Universitatea Politehnica Timisoara, aflat in faza de pregatire cu partenerii universitari.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#6a1b9a;font-weight:bold;">Agenda:</span> Standuri de prezentare, interviuri rapide si sesiuni de informare despre programele de internship.</li><li><span style="color:#6a1b9a;font-weight:bold;">Public tinta:</span> Studenti si proaspeti absolventi din Timisoara.</li><li><span style="color:#6a1b9a;font-weight:bold;">Inclus:</span> Materiale de prezentare in curs de pregatire.</li></ul><p style="color:#607d8b;"><em>Publicarea oficiala va avea loc dupa confirmarea partenerilor.</em></p>', decode('','base64'), false, NULL, '405829'),
('20000015-0000-0000-0000-000000000000', '10000015-0000-0000-0000-000000000000', '<p>Workshop in curs de pregatire, dedicat celor mai bune practici de securitate cibernetica pentru toti angajatii.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Sesiuni practice, demonstratii si discutii despre politicile de securitate.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Toti angajatii, in special echipele tehnice.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Materiale de curs in curs de finalizare.</li></ul><p style="color:#607d8b;"><em>Programul complet va fi publicat imediat ce planificarea este gata.</em></p>', decode('','base64'), true, NULL, '618273'),
('20000016-0000-0000-0000-000000000000', '10000016-0000-0000-0000-000000000000', '<p>Eveniment de recrutare organizat impreuna cu Universitatea de Medicina, Farmacie, Stiinte si Tehnologie din Targu Mures.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#6a1b9a;font-weight:bold;">Agenda:</span> Standuri de prezentare, workshop-uri de CV si interviuri pe loc.</li><li><span style="color:#6a1b9a;font-weight:bold;">Public tinta:</span> Studenti si proaspeti absolventi din regiunea Mures.</li><li><span style="color:#6a1b9a;font-weight:bold;">Inclus:</span> Acces liber la toate standurile si sesiunile de informare.</li></ul><p style="color:#607d8b;"><em>Va asteptam cu drag sa ne cunoastem echipa.</em></p>', decode('','base64'), false, NULL, '153940'),
('20000017-0000-0000-0000-000000000000', '10000017-0000-0000-0000-000000000000', '<p>Zi a portilor deschise la biroul din Cluj, dedicata celor curiosi sa afle cum arata o zi de lucru in compania noastra.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#6a1b9a;font-weight:bold;">Agenda:</span> Tur ghidat al biroului, prezentari despre proiecte si sesiune de intrebari si raspunsuri.</li><li><span style="color:#6a1b9a;font-weight:bold;">Public tinta:</span> Candidati interesati si publicul larg.</li><li><span style="color:#6a1b9a;font-weight:bold;">Inclus:</span> Gustari si materiale de prezentare despre companie.</li></ul><p style="color:#607d8b;"><em>Inscrierile sunt deschise, locurile fiind limitate.</em></p>', decode('','base64'), false, NULL, '826705'),
('20000018-0000-0000-0000-000000000000', '10000018-0000-0000-0000-000000000000', '<p>Intalnire dedicata femeilor din tehnologie, cu discutii despre cariera, mentorat si echilibrul viata-munca.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Discutii deschise, sesiune de mentorat si networking.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Colege din departamentele tehnice si HR.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Gustari usoare si materiale de mentorat.</li></ul><p style="color:#607d8b;"><em>Va asteptam pentru o intalnire plina de inspiratie.</em></p>', decode('','base64'), true, NULL, '490318'),
('20000019-0000-0000-0000-000000000000', '10000019-0000-0000-0000-000000000000', '<p>Zi de distractie in aer liber pentru angajati si familiile lor, organizata la biroul din Timisoara.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#00695c;font-weight:bold;">Agenda:</span> Activitati pentru copii, jocuri de echipa si gratar in aer liber.</li><li><span style="color:#00695c;font-weight:bold;">Public tinta:</span> Angajati si familiile acestora.</li><li><span style="color:#00695c;font-weight:bold;">Inclus:</span> Mancare la gratar, bauturi racoritoare si activitati pentru copii.</li></ul><p style="color:#607d8b;"><em>Un eveniment perfect pentru timp de calitate alaturi de cei dragi.</em></p>', decode('','base64'), true, NULL, '372681'),
('20000020-0000-0000-0000-000000000000', '10000020-0000-0000-0000-000000000000', '<p>Deschiderea oficiala a programului de internship de vara, dedicat noilor stagiari din companie.</p><ul style="margin:8px 0;padding-left:20px;"><li><span style="color:#1565c0;font-weight:bold;">Agenda:</span> Prezentare generala, cunoasterea mentorilor si stabilirea obiectivelor de invatare.</li><li><span style="color:#1565c0;font-weight:bold;">Public tinta:</span> Stagiari nou-veniti si mentorii acestora.</li><li><span style="color:#1565c0;font-weight:bold;">Inclus:</span> Materiale de curs, pranz si un kit de bun venit.</li></ul><p style="color:#607d8b;"><em>Va uram succes in aceasta experienta de invatare.</em></p>', decode('','base64'), true, NULL, '905462')
